    private static function reviewFindingPartition(array $audit): array
    {
        $automated=['errors'=>[],'warnings'=>[]];$presentation=[];$isPresentation=static fn(string$text): bool=>preg_match('/artwork|story image|active image .*alternative text|alternative text|media asset/i',$text)===1;
