    }

    private static function reviewChecklist(string $reviewType): array
    {
        return match($reviewType){
            'whats_next'=>['prioritize automated blockers','identify missing authored data','suggest the next highest-value task'],
            'quality_check'=>['score immersion and viewpoint continuity','score agency, causality, dependencies, pacing, replayability, and mobile readability','cite evidence from the supplied fields'],
            'dependencies'=>['check references between decisions, options, effects, conditions, values, and endings','find inactive or undefined references','separate structural evidence from inference'],
            'review_characters'=>['review every active character','check knowledge boundaries, goals, fears, agency, and viewpoint continuity','identify authored-data or prose fixes'],
            'story_values'=>['review existing managed Story Framework values','find missing or weak values needed by effects, conditions, endings, and knowledge','suggest only values that fit the supplied story'],
            'review_opportunities'=>['review every active decision opportunity','check prompts, agency, option contrast, consequences, conditions, effects, rationale, knowledge, and readability'],
            'focused_tests'=>['identify the highest-risk authored branches','choose validation, focused-opportunity, broad-simulation, or manual-smoke tests','do not claim tests were run'],
            'review_consistency'=>['trace story data from premise through characters, events, decisions, opportunities, and endings','check that player-facing cause and effect stays consistent across the authored records','separate confirmed conflicts from risks that require manual review'],
            default=>['review the authored premise and player-facing prose','check chronology, agency, branch causality, dependencies, reachability, pacing, replayability, and mobile readability','cite named stable keys for every finding and recommendation'],
        };
    }

    private static function reviewRows(array $rows,array $fields,int $limit,int $maxRows): array
    {
        $out=[];foreach(array_slice($rows,0,$maxRows)as$row)if(is_array($row))$out[]=self::reviewRow($row,$fields,$limit);return$out;
    }

    private static function reviewRow(array $row,array $fields,int $limit=400): array
    {
        $out=[];foreach($fields as$field)if(array_key_exists($field,$row)){$value=$row[$field];if(is_string($value)){$length=function_exists('mb_strlen')?mb_strlen($value):strlen($value);if($length>$limit)$value=(function_exists('mb_substr')?mb_substr($value,0,$limit):substr($value,0,$limit)).' [PACKAGE_TRUNCATED]';}$out[$field]=$value;}return$out;
    }

    private static function reviewStableKeys(array $plot,array $workspace): array
    {
        $keys=[];
        $add=static function (mixed $value) use (&$keys): void {
            $value=trim((string)$value);
            if($value!=='')$keys[]=self::stableCode($value);
        };
        $add($plot['code']??'');
        $fieldsBySection=[
            'locations'=>['location_code','label_text'],
            'state_definitions'=>['target_code'],
            'characters'=>['role_code'],
            'events'=>['event_code'],
            'decisions'=>['event_code','role_code'],
            'options'=>['option_code'],
            'effects'=>['option_code','target_code'],
            'opportunities'=>['opportunity_code'],
            'dynamic_conditions'=>['opportunity_code','source_key'],
            'dynamic_options'=>['option_code'],
            'dynamic_effects'=>['option_code','target_code'],
            'story_sections'=>['section_code'],
            'resolutions'=>['section_code'],
            'resolution_conditions'=>['section_code','state_key'],
        ];
        foreach($fieldsBySection as $section=>$fields){
            foreach($workspace[$section]??[] as $row){
                foreach($fields as $field)$add($row[$field]??'');
            }
        }
        foreach($workspace['decisions']??[] as $row){
            $add((string)($row['event_code']??'').'_' . (string)($row['role_code']??''));
        }
        foreach($workspace['options']??[] as $row){
            $add((string)($row['event_code']??'').'_' . (string)($row['role_code']??'').'_' . (string)($row['option_code']??''));
        }
        return array_values(array_unique($keys));
    }

    private static function reviewRoleCodes(array $workspace): array
    {
        $codes=[];foreach($workspace['characters']??[]as$row){$code=self::stableCode((string)($row['role_code']??''));if($code!=='')$codes[]=$code;}return array_values(array_unique($codes));
    }

    private static function reviewOpportunityCodes(array $workspace): array
    {
        $codes=[];foreach($workspace['opportunities']??[]as$row){$code=self::stableCode((string)($row['opportunity_code']??''));if($code!=='')$codes[]=$code;}return array_values(array_unique($codes));
    }

