    private static function reviewRepairPrompt(string $purpose,array $audit): string
    {
        $context=['review_request'=>$purpose,'visibility_rules'=>['decision_prompt_text'=>'acting_role_only','character_private_knowledge'=>'role_only','managed_story_values'=>'authoring_metadata_unless_repeated'],'review_boundaries'=>['automated_findings'=>'authoritative structural diagnostics; do not invent or paraphrase extra defects','replacement_values'=>'use only exact supplied keys and allowed values'],'stable_key_catalog'=>array_values((array)($audit['stable_keys']??[])),'role_code_catalog'=>array_values((array)($audit['role_codes']??[])),'opportunity_code_catalog'=>array_values((array)($audit['opportunity_codes']??[])),'automated_findings'=>['errors'=>array_slice(array_values($audit['errors']??[]),0,8),'warnings'=>array_slice(array_values($audit['warnings']??[]),0,8)]];
        $json=json_encode($context,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);if($json===false)$json='{}';$fields=$purpose==='INKY_STORY_CONSISTENCY'?' Include non-empty field, problem, proposed_change, and verification properties on every recommendation.':'';
        return'VALIDATION CORRECTION: Return only the JSON shape specified in the system instruction. The previous response was unusable; repair its structure and citations without inventing findings. Automated findings are authoritative structural diagnostics: do not add or reinterpret them as qualitative defects. Cite only exact catalog values and allowed values supplied in the package, use an empty result array when the compact evidence does not support an item, and never treat role-only prompts or authoring metadata as public player-facing content. Keep recommendations concrete.'.$fields.' COMPACT VALIDATION CONTEXT: '.$json;
