":[{"stable_key":"KEY","field":"exact authored field name","severity":"BLOCKER|HIGH|MEDIUM|LOW","category":"one consistency category","problem":"specific confirmed problem","proposed_change":"copy-ready replacement wording or exact authored-data change","verification":"specific way to verify the correction","manual_structural_review":false}]}. Return 0 to 6 recommendations, keep each item short enough to read on a phone, return no markdown, and return no additional keys.';
